-- +goose Up
-- Identity, sessions, organizations and audit log (PLAN §8.1, §8.2, §10.2).
-- Primary keys are UUID v7 generated by the application.

-- One namespace for users and organizations: "/<name>/..." must be unique
-- whatever the kind, compared case-insensitively.
CREATE TABLE namespaces (
    id         uuid        PRIMARY KEY,
    kind       text        NOT NULL CHECK (kind IN ('user', 'org')),
    name       text        NOT NULL CHECK (name ~ '^[A-Za-z0-9](-?[A-Za-z0-9])*$' AND length(name) <= 39),
    name_lower text        GENERATED ALWAYS AS (lower(name)) STORED UNIQUE,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id           uuid        PRIMARY KEY REFERENCES namespaces (id) ON DELETE CASCADE,
    display_name text        NOT NULL DEFAULT '',
    -- Instance role (PLAN §5.3).
    role         text        NOT NULL DEFAULT 'user' CHECK (role IN ('admin', 'user', 'restricted')),
    locale       text        NOT NULL DEFAULT 'en' CHECK (locale IN ('en', 'it')),
    suspended_at timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE emails (
    id            uuid        PRIMARY KEY,
    user_id       uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    address       text        NOT NULL CHECK (length(address) BETWEEN 3 AND 254),
    address_lower text        GENERATED ALWAYS AS (lower(address)) STORED UNIQUE,
    is_primary    boolean     NOT NULL DEFAULT false,
    verified_at   timestamptz,
    created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX emails_one_primary ON emails (user_id) WHERE is_primary;

-- Local password, absent for accounts that only use OIDC or passkeys.
CREATE TABLE passwords (
    user_id    uuid        PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    hash       text        NOT NULL, -- argon2id PHC string
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Browser sessions. Only the SHA-256 of the 256-bit cookie token is stored.
CREATE TABLE sessions (
    id           uuid        PRIMARY KEY,
    token_hash   bytea       NOT NULL UNIQUE CHECK (length(token_hash) = 32),
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    csrf_token   text        NOT NULL,
    ip           text        NOT NULL DEFAULT '',
    user_agent   text        NOT NULL DEFAULT '',
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL -- absolute expiry; idle expiry is last_seen_at + idle timeout
);

CREATE INDEX sessions_user ON sessions (user_id);
CREATE INDEX sessions_expires ON sessions (expires_at);

-- Single-use tokens sent by mail (email verification, password reset).
CREATE TABLE one_time_tokens (
    token_hash bytea       PRIMARY KEY CHECK (length(token_hash) = 32),
    purpose    text        NOT NULL CHECK (purpose IN ('verify_email', 'reset_password')),
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    email_id   uuid        REFERENCES emails (id) ON DELETE CASCADE,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX one_time_tokens_user ON one_time_tokens (user_id, purpose);

-- Instance invitations, required to register when registration = "invite".
CREATE TABLE invites (
    id         uuid        PRIMARY KEY,
    token_hash bytea       NOT NULL UNIQUE CHECK (length(token_hash) = 32),
    email      text,       -- when set, only this address can use the invite
    created_by uuid        REFERENCES users (id) ON DELETE SET NULL,
    expires_at timestamptz NOT NULL,
    used_at    timestamptz,
    used_by    uuid        REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE orgs (
    id           uuid        PRIMARY KEY REFERENCES namespaces (id) ON DELETE CASCADE,
    display_name text        NOT NULL DEFAULT '',
    description  text        NOT NULL DEFAULT '',
    verified_at  timestamptz, -- set by an instance admin (PLAN §8.2)
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE org_members (
    org_id     uuid        NOT NULL REFERENCES orgs (id) ON DELETE CASCADE,
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role       text        NOT NULL CHECK (role IN ('owner', 'member', 'billing')),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (org_id, user_id)
);

CREATE INDEX org_members_user ON org_members (user_id);

-- Append-only security log (PLAN §8.3). Never holds secrets or tokens.
CREATE TABLE audit_log (
    id          uuid        PRIMARY KEY,
    at          timestamptz NOT NULL DEFAULT now(),
    actor_id    uuid,       -- no foreign key: entries outlive deleted users
    action      text        NOT NULL,
    target_type text        NOT NULL DEFAULT '',
    target_id   text        NOT NULL DEFAULT '',
    ip          text        NOT NULL DEFAULT '',
    data        jsonb       NOT NULL DEFAULT '{}'
);

CREATE INDEX audit_log_at ON audit_log (at);
CREATE INDEX audit_log_actor ON audit_log (actor_id, at);
CREATE INDEX audit_log_action ON audit_log (action, at);
